// ---------------------------------------------------------------- stair 3: multiplying and dividing
// The model: multiplying is repeated adding (jumps on the line); a pattern table shows why (−)·(−) is (+);
// dividing is the inverse of multiplying, so it keeps the same sign rule.

type MulDiv = { f: number; a: number; b: number; c: number }; // f = 0: a·b, 1: a : b, 2: a·b·c
const mdValue = (p: MulDiv) => (p.f === 0 ? p.a * p.b : p.f === 1 ? p.a / p.b : p.a * p.b * p.c);
const mdShow = (p: MulDiv) => (p.f === 0 ? `${T(p.a, true)} \\cdot ${T(p.b, true)}`
  : p.f === 1 ? `${T(p.a, true)} : ${T(p.b, true)}` : `${T(p.a, true)} \\cdot ${T(p.b, true)} \\cdot ${T(p.c, true)}`);
/** The answer the sign rule of ADDITION gives (same signs keep the sign; different signs take the sign of the farther). */
const addRuleSign = (a: number, b: number, value: number): number | null => {
  const m = Math.abs(value);
  if (sgn(a) === sgn(b)) return sgn(a) * m;
  if (Math.abs(a) === Math.abs(b)) return null;
  return (Math.abs(a) > Math.abs(b) ? sgn(a) : sgn(b)) * m;
};

const mulDivModel: DiagModel<MulDiv> = {
  params: (rnd) => {
    const r = rnd();
    if (r < 0.45) { // two factors, at least one negative
      let a = rint(rnd, 2, 12); let b = rint(rnd, 2, 9);
      if (rnd() < 0.4) { a = -a; b = -b; } else if (rnd() < 0.5) a = -a; else b = -b;
      return { f: 0, a, b, c: 1 };
    }
    if (r < 0.8) { // a division that comes out whole
      let b = rint(rnd, 2, 9); let q = rint(rnd, 2, 10);
      if (rnd() < 0.4) b = -b; else { q = -q; if (rnd() < 0.5) b = -b; }
      return { f: 1, a: q * b, b, c: 1 };
    }
    // three factors: three, two or one of them negative
    const neg = rnd() < 0.5 ? 3 : rnd() < 0.6 ? 2 : 1;
    const v = [rint(rnd, 2, 5), rint(rnd, 2, 5), rint(rnd, 2, 5)];
    mix([0, 1, 2], rnd).slice(0, neg).forEach((i) => { v[i] = -v[i]; });
    return { f: 2, a: v[0], b: v[1], c: v[2] };
  },
  text: () => 'احسبوا:',
  display: mdShow,
  answer: mdValue,
  bugs: {
    // the size is right, the sign is not
    sign: (p) => -mdValue(p),
    // the sign rule of addition used for × and ÷: (−3)·(−4) = −12, 8·(−2) = +16
    'add-sign': (p) => (p.f === 2 ? null : addRuleSign(p.a, p.b, mdValue(p))),
    // "minus times minus is plus" stretched to three negative factors
    'neg-many': (p) => (p.f === 2 && p.a < 0 && p.b < 0 && p.c < 0 ? -mdValue(p) : null),
  },
  solution: (p) => {
    const ans = mdValue(p);
    if (p.f === 2) {
      const n = [p.a, p.b, p.c].filter((x) => x < 0).length;
      return [
        `نعدّ العوامل السالبة: ${n}. ${n % 2 === 0 ? 'عدد زوجي: كل زوج من إشارات الناقص يعطي زائد، والنتيجة موجبة.' : 'عدد فردي: تبقى إشارة ناقص واحدة، والنتيجة سالبة.'}`,
        `المقدار: $${Math.abs(p.a)} \\cdot ${Math.abs(p.b)} \\cdot ${Math.abs(p.c)} = ${Math.abs(ans)}$`,
        `الإجابة: $${T(ans)}$`,
      ];
    }
    const out = [
      `الإشارة: ${sgn(p.a) === sgn(p.b) ? 'إشارتان متساويتان، لذلك النتيجة موجبة' : 'إشارتان مختلفتان، لذلك النتيجة سالبة'}.`,
      `المقدار: $${Math.abs(p.a)} ${p.f === 0 ? '\\cdot' : ':'} ${Math.abs(p.b)} = ${Math.abs(ans)}$`,
      `الإجابة: $${T(ans)}$`,
    ];
    if (p.f === 1) out.push(`فحص بالضرب: $${T(ans, true)} \\cdot ${T(p.b, true)} = ${T(p.a)}$`);
    return out;
  },
  hint: (p) => (p.f === 2
    ? 'اضربوا اثنين اثنين، أو عدّوا العوامل السالبة: العدد الزوجي يعطي موجبًا، والعدد الفردي يعطي سالبًا.'
    : `أولًا الإشارة: إشارتان متساويتان تعطيان موجبًا، وإشارتان مختلفتان تعطيان سالبًا. بعد ذلك المقدار، من دون الإشارات.${p.f === 1 ? ' يمكن فحص القسمة بالضرب.' : ''}`),
};

type Rate = { k: number; r: number; t: number }; // a temperature that falls r degrees an hour; k = 0 later, 1 earlier, 2 the rate itself
const rateValue = (p: Rate) => (p.k === 0 ? -p.t * p.r : p.k === 1 ? p.t * p.r : -p.r);
const rateModel: DiagModel<Rate> = {
  params: (rnd) => ({ k: rint(rnd, 0, 2), r: rint(rnd, 2, 6), t: rint(rnd, 2, 6) }),
  text: (p) => (p.k === 0
    ? `في الليل تنخفض درجة الحرارة بالوتيرة نفسها: $${p.r}$ درجات كل ساعة. بكم درجة ستتغيّر بعد $${p.t}$ ساعات؟ (الانخفاض يُكتب كعدد سالب.)`
    : p.k === 1
      ? `في الليل تنخفض درجة الحرارة بالوتيرة نفسها: $${p.r}$ درجات كل ساعة. الآن $0$ درجة. كم كانت درجة الحرارة قبل $${p.t}$ ساعات؟`
      : `خلال $${p.t}$ ساعات انخفضت درجة الحرارة بالمجموع $${p.t * p.r}$ درجات، بالوتيرة نفسها كل ساعة. ما التغيّر في كل ساعة؟ (الانخفاض يُكتب كعدد سالب.)`),
  answer: rateValue,
  bugs: {
    sign: (p) => -rateValue(p),
    // the factors are t·(−r), (−t)·(−r) and (−t·r) : t
    'add-sign': (p) => (p.k === 0 ? addRuleSign(p.t, -p.r, rateValue(p)) : p.k === 1 ? addRuleSign(-p.t, -p.r, rateValue(p)) : addRuleSign(-p.t * p.r, p.t, rateValue(p))),
  },
  solution: (p) => (p.k === 0
    ? [`في كل ساعة التغيّر $${T(-p.r)}$. بعد $${p.t}$ ساعات: $${p.t} \\cdot ${T(-p.r, true)}$.`, `إشارتان مختلفتان، لذلك سالب: $${p.t} \\cdot ${T(-p.r, true)} = ${T(-p.t * p.r)}$.`, `ستنخفض درجة الحرارة ${p.t * p.r} درجات: تغيّر مقداره $${T(-p.t * p.r)}$.`]
    : p.k === 1
      ? [`الزمن الذي مضى زمن سالب: قبل $${p.t}$ ساعات هو $${T(-p.t)}$.`, `درجة الحرارة حينها: $${T(-p.t, true)} \\cdot ${T(-p.r, true)} = ${p.t * p.r}$ درجات.`, `فحص: من $${p.t * p.r}$ درجات انخفضت $${p.t}$ مرات $${p.r}$ درجات ووصلت إلى $0$.`]
      : [`التغيّر الكلّي $${T(-p.t * p.r)}$، ونقسمه على $${p.t}$ ساعات.`, `إشارتان مختلفتان، لذلك سالب: $${T(-p.t * p.r, true)} : ${p.t} = ${T(-p.r)}$.`, `فحص: $${p.t} \\cdot ${T(-p.r, true)} = ${T(-p.t * p.r)}$.`]),
  hint: (p) => (p.k === 0 ? 'كل ساعة تضيف تغيّر انخفاض آخر. نضرب عدد الساعات في تغيّر ساعة واحدة.'
    : p.k === 1 ? 'فكّروا في فيديو يعود إلى الوراء: عندما نرجع في الزمن، يصبح الانخفاض ارتفاعًا. الزمن الذي مضى زمن سالب.'
      : 'التغيّر في ساعة واحدة = التغيّر الكلّي مقسومًا على عدد الساعات. الانخفاض تغيّر سالب.'),
};

