type Groups = { k: number; a: number; b: number; c: number; n: number }; // k = 0: a deposit and a withdrawal cancelled; 1: n rounds of +b and −c
const groupsValue = (p: Groups) => (p.k === 0 ? p.a - (p.b - p.c) : p.a + p.n * (p.b - p.c));
const groupsModel: DiagModel<Groups> = {
  params: (rnd) => {
    const k = rnd() < 0.5 ? 0 : 1;
    for (;;) {
      const b = k === 0 ? rint(rnd, 5, 40) : rint(rnd, 1, 9); const c = k === 0 ? rint(rnd, 5, 40) : rint(rnd, 1, 9);
      if (b === c) continue;
      return k === 0 ? { k, a: rint(rnd, 10, 60), b, c, n: 1 } : { k, a: rint(rnd, -10, 20), b, c, n: rint(rnd, 2, 5) };
    }
  },
  text: (p) => (p.k === 0
    ? `في حساب نوعا في البنك كان $${p.a}$ ₪. اكتشف البنك أن عمليتين سُجّلتا بالخطأ، فألغاهما: إيداع $${p.b}$ ₪ وسحب $${p.c}$ ₪. كم مالًا في الحساب الآن؟`
    : `في لعبة ${hadPoints('مع رون', p.a)}. بعد ذلك لعب $${p.n}$ جولات، وفي كل جولة ربح ${points(p.b)} وخسر ${points(p.c)}. كم نقطة معه الآن؟`),
  answer: groupsValue,
  bugs: {
    // cancelling the pair: the deposit taken away, the withdrawal taken away too
    'minus-bracket': (p) => (p.k === 0 ? p.a - p.b - p.c : null),
    'minus-minus': (p) => (p.k === 0 && p.b - p.c < 0 ? p.a + (p.b - p.c) : null),
    // the rounds multiply only what was won, not what was lost
    'ignore-brackets': (p) => (p.k === 1 ? p.a + p.n * p.b - p.c : null),
    order: (p) => (p.k === 1 ? (p.a + p.n) * (p.b - p.c) : null),
  },
  solution: (p) => {
    const inner = p.b - p.c; const ans = groupsValue(p);
    return p.k === 0
      ? [`العمليتان رزمة واحدة: $(${p.b} - ${p.c})$. الإلغاء هو طرح الرزمة: $${p.a} - (${p.b} - ${p.c})$.`,
        `نفتح الأقواس: إلغاء الإيداع يُنقص $${p.b}$، وإلغاء السحب يعيد $${p.c}$: $${p.a} - ${p.b} + ${p.c} = ${T(ans)}$.`,
        `في الحساب الآن $${T(ans)}$ ₪.`]
      : [`في كل جولة التغيّر رزمة واحدة: $${p.b} - ${p.c} = ${T(inner)}$.`,
        `$${p.n}$ جولات: $${T(p.a)} + ${p.n} \\cdot (${p.b} - ${p.c}) = ${T(p.a)} + ${p.n} \\cdot ${T(inner, true)}$.`,
        `أولًا الضرب: $${p.n} \\cdot ${T(inner, true)} = ${T(p.n * inner)}$، ثم $${T(p.a)} + ${T(p.n * inner, true)} = ${T(ans)}$ نقاط.`];
  },
  hint: (p) => (p.k === 0 ? 'إلغاء الإيداع يُنقص مالًا، وإلغاء السحب يعيد مالًا.' : 'بكم تغيّرت النقاط في جولة واحدة؟ هذه رزمة، وكل جولة تكرّرها.'),
};

